function offsetPts(pts, off) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[Math.max(0, i - 1)];
    const b = pts[Math.min(pts.length - 1, i + 1)];
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const len = Math.hypot(dx, dy) || 1;
    out.push([pts[i][0] - (dy / len) * off, pts[i][1] + (dx / len) * off]);
  }
  return out;
}

function smoothPath(pts) {
  if (pts.length < 2) return "";
  let d = "M" + pts[0][0].toFixed(1) + " " + pts[0][1].toFixed(1);
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    const c1x = p1[0] + (p2[0] - p0[0]) / 6;
    const c1y = p1[1] + (p2[1] - p0[1]) / 6;
    const c2x = p2[0] - (p3[0] - p1[0]) / 6;
    const c2y = p2[1] - (p3[1] - p1[1]) / 6;
    d += " C" + c1x.toFixed(1) + " " + c1y.toFixed(1) + " " + c2x.toFixed(1) + " " + c2y.toFixed(1) + " " + p2[0].toFixed(1) + " " + p2[1].toFixed(1);
  }
  return d;
}

function wave(x0, y0, x1, y1, amp, freq, samples, phase) {
  const pts = [];
  for (let i = 0; i <= samples; i++) {
    const t = i / samples;
    const x = x0 + (x1 - x0) * t;
    const y = y0 + (y1 - y0) * t;
    const nx = -(y1 - y0);
    const ny = x1 - x0;
    const nl = Math.hypot(nx, ny) || 1;
    const w = Math.sin(t * Math.PI * freq + phase) * amp * Math.sin(t * Math.PI);
    pts.push([x + (nx / nl) * w, y + (ny / nl) * w]);
  }
  return pts;
}

function strokeNoodle(g, pts, width, stroke, opacity) {
  el("path", {
    d: smoothPath(pts),
    stroke: stroke,
    "stroke-width": String(width),
    opacity: String(opacity)
  }, g);
}

function drawNoodles() {
  const g = document.getElementById("noodles");
  const bands = [
    [150, 300, 360, 210, 22, 2.4, 0.2],
    [140, 250, 370, 280, 18, 2.1, 1.1],
    [170, 340, 355, 250, 20, 2.6, 0.6],
    [165, 220, 340, 345, 16, 1.8, 2.2],
    [200, 190, 330, 330, 19, 2.3, 0.4],
    [130, 280, 380, 320, 14, 2.0, 1.7],
    [190, 360, 350, 200, 17, 2.5, 0.9],
    [175, 205, 300, 355, 15, 1.9, 2.8]
  ];
  bands.forEach((b) => {
    const base = wave(b[0], b[1], b[2], b[3], b[4], b[5], 18, b[6]);
    for (let k = -2; k <= 2; k++) {
      const pts = offsetPts(base, k * 7.2);
      strokeNoodle(g, pts, 8.6, "url(#ndDeep)", 0.4);
      strokeNoodle(g, pts, 6.6, "url(#ndMid)", 0.95);
      if (k === -1 || k === 1) strokeNoodle(g, offsetPts(pts, 1.4), 1.8, "url(#ndHi)", 0.42);
    }
  });
}

