import { chromium } from "<HOME>/.npm/_npx/bbb8a2c4738e2b0c/node_modules/playwright-core/index.mjs";

const chrome = "<HOME>/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome";
const out = "<TMP>/ramen-screens";

const browser = await chromium.launch({
  executablePath: chrome,
  headless: true,
  args: ["--disable-gpu", "--no-sandbox"],
});

async function shot(name, { w, h, reduced, mouse }) {
  const context = await browser.newContext({
    viewport: { width: w, height: h },
    deviceScaleFactor: 1,
    reducedMotion: reduced ? "reduce" : "no-preference",
  });
  const page = await context.newPage();
  await page.goto("http://<LAN_IP>:8766/index.html", { waitUntil: "networkidle" });
  await page.waitForTimeout(900);
  if (mouse) {
    await page.mouse.move(mouse[0], mouse[1], { steps: 12 });
    await page.waitForTimeout(400);
  }
  await page.screenshot({ path: `${out}/${name}.png` });
  await context.close();
}

await shot("desktop", { w: 1440, h: 900 });
